// Generates src/generated/types.ts and src/generated/schema.ts from schemas/v1.schema.json.
// The JSON Schema is the source of truth; never edit the generated files by hand.
// `npm run check:generated` at the repository root fails if they drift.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');
const schema = JSON.parse(readFileSync(join(root, 'schemas/v1.schema.json'), 'utf8'));

const defs = {};
for (const [name, def] of Object.entries(schema.$defs)) {
  // if/then status coupling is a validation rule, not a type shape; the generator cannot express it.
  const { allOf, ...shape } = def;
  defs[name] = { ...shape, title: name };
}
const wrapper = {
  title: 'V1Contracts',
  type: 'object',
  additionalProperties: false,
  properties: Object.fromEntries(Object.keys(defs).map((n) => [n, { $ref: `#/$defs/${n}` }])),
  $defs: defs,
};

const banner = '/* Generated by packages/contracts/scripts/generate-types.mjs from schemas/v1.schema.json. Do not edit. */';
let ts = await compile(wrapper, 'V1Contracts', {
  bannerComment: banner,
  additionalProperties: false,
  unreachableDefinitions: true,
  strictIndexSignatures: true,
  format: true,
  style: { singleQuote: true, printWidth: 110 },
});
ts = ts.replace(/export interface V1Contracts \{[\s\S]*?\n\}\n/, '');
writeFileSync(join(root, 'src/generated/types.ts'), ts);

const schemaTs = `${banner}\n/* eslint-disable */\nexport const v1Schema = ${JSON.stringify(schema, null, 2)} as const;\n`;
writeFileSync(join(root, 'src/generated/schema.ts'), schemaTs);
console.log(`generated ${Object.keys(defs).length} definitions`);
